def gpx_fields_to_xml(instance: Any, tag: str, version: str,
    custom_attributes: Dict[str, str]={}, nsmap: Dict[str, str]={},
    prettyprint: bool=True, indent: str='', empty_body: bool=False) ->str:
    if not prettyprint:
        indent = ''
    fields = instance.gpx_10_fields
    if version == '1.1':
        fields = fields + instance.gpx_11_fields

    body = []
    attributes = []
    tag_stack = []
    current_body_stack = [body]

    for field in fields:
        if isinstance(field, str):
            if field.startswith('/'):
                if tag_stack:
                    inner_tag = tag_stack.pop()
                    inner_body = current_body_stack.pop()
                    inner_content = ''.join(inner_body)
                    current_indent = indent + '  ' * len(tag_stack)
                    if inner_content:
                        if prettyprint:
                            entry = f'\n{current_indent}<{inner_tag}>{inner_content}\n{current_indent}</{inner_tag}>'
                        else:
                            entry = f'<{inner_tag}>{inner_content}</{inner_tag}>'
                    else:
                        if prettyprint:
                            entry = ''
                        else:
                            entry = ''
                    if entry:
                        current_body_stack[-1].append(entry)
            else:
                tag_stack.append(field)
                current_body_stack.append([])
            continue
        value = getattr(instance, field.name)
        current_indent = indent + '  ' * (len(tag_stack) + 1)
        if field.attribute:
            xml_value = field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=current_indent)
            if xml_value:
                attributes.append(xml_value)
        else:
            xml_value = field.to_xml(value, version, nsmap, prettyprint=prettyprint, indent=current_indent)
            if xml_value:
                current_body_stack[-1].append(xml_value)

    for attr_name, attr_value in custom_attributes.items():
        attributes.append(f'{attr_name}="{attr_value}"')

    result = []
    if tag:
        attr_str = (' ' + ' '.join(attributes)) if attributes else ''
        body_str = ''.join(body)
        if body_str or empty_body:
            if prettyprint:
                result.append(f'\n{indent}<{tag}{attr_str}>')
            else:
                result.append(f'<{tag}{attr_str}>')
            result.append(body_str)
            if prettyprint:
                result.append(f'\n{indent}</{tag}>')
            else:
                result.append(f'</{tag}>')
        else:
            if prettyprint:
                result.append(f'\n{indent}<{tag}{attr_str} />')
            else:
                result.append(f'<{tag}{attr_str} />')
    else:
        result.append(''.join(body))

    return ''.join(result)
