        fields = fields + instance.gpx_11_fields

    node_stack = [node]

    for field in fields:
        if isinstance(field, str):
            if field.startswith('/'):
                if len(node_stack) > 1:
                    node_stack.pop()
            else:
                if node_stack[-1] is not None:
                    child = node_stack[-1].find(field)
                else:
                    child = None
                node_stack.append(child)
            continue
        current_node = node_stack[-1]
        if current_node is None:
            if field.is_list:
                setattr(instance, field.name, [])
