def parse_time(string: str) ->Optional[mod_datetime.datetime]:
    if not string:
        return None
    m = RE_TIMESTAMP.match(string.strip())
    if not m:
        return None
    year, month, day, hour, minute, second = (int(m.group(i)) for i in range(1, 7))
    microsecond = 0
    if m.group(7):
        frac = m.group(7)[1:]
        frac = frac[:6]
        frac = frac.ljust(6, '0')
        microsecond = int(frac)
    tz_str = m.group(8)
    if tz_str is None:
        tzinfo = None
    elif tz_str == 'Z':
        tzinfo = SimpleTZ()
