def format_time(time: mod_datetime.datetime) ->str:
    if not time:
        return ''
    tzinfo = time.tzinfo
    if tzinfo is None:
        tz_str = ''
    elif isinstance(tzinfo, SimpleTZ):
        if tzinfo.offset == 0:
            tz_str = 'Z'
        else:
            offset = tzinfo.offset
            sign = '+' if offset >= 0 else '-'
            offset = abs(offset)
            tz_str = f'{sign}{offset // 60:02}:{offset % 60:02}'
    else:
        offset = tzinfo.utcoffset(time)
        if offset is None:
            tz_str = ''
        else:
            total_seconds = int(offset.total_seconds())
            sign = '+' if total_seconds >= 0 else '-'
            total_seconds = abs(total_seconds)
            hours, remainder = divmod(total_seconds, 3600)
            minutes = remainder // 60
            tz_str = f'{sign}{hours:02}:{minutes:02}'
    if time.microsecond:
        return time.strftime(f'%Y-%m-%dT%H:%M:%S.{time.microsecond:06d}') + tz_str
    return time.strftime('%Y-%m-%dT%H:%M:%S') + tz_str
